Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchButton(
        text = {{back}},
        onClick = {},
        variant = MonarchButtonVariant.Ghost,
        size = MonarchButtonSize.Sm,
        leadingIcon = { MonarchIcon(imageVector = SampleIcons.ChevronLeft, contentDescription = null) },
    )
    Row(
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.Top,
    ) {
        MonarchAvatar(image = null, name = {{name}}, size = MonarchAvatarSize.Lg, decorative = true)
        Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            FlowRow(
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
                itemVerticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchText(
                    text = {{name}},
                    style = MonarchTextStyle.Title,
                    modifier = Modifier.semantics { heading() },
                )
                MonarchStatusBadge(definition = MonarchStatusDefinition({{status.label}}, {{status.tone|tone}}))
                MonarchBadge(text = {{badge.label}}, tone = {{badge.tone|tone}})
            }
            MonarchText(text = {{subtitle}}, style = MonarchTextStyle.Caption)
        }
    }
    // On a phone the actions sit under the name instead of beside it.
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchButton(text = {{action}}, onClick = {}, variant = MonarchButtonVariant.Secondary)
        Box {
            MonarchIconButton(
                label = "More actions for " + {{name}},
                onClick = { menuOpen = true },
                variant = MonarchButtonVariant.Secondary,
            ) {
                MonarchIcon(SampleIcons.MoreVertical, contentDescription = null)
            }
            MonarchMenu(expanded = menuOpen, onDismissRequest = { menuOpen = false }) {
                MonarchMenuItem(text = {{menu.0}}, onClick = { menuOpen = false })
                MonarchMenuItem(text = {{menu.1}}, onClick = { menuOpen = false })
                MonarchMenuItem(text = {{menu.2}}, onClick = { menuOpen = false }, destructive = true)
            }
        }
    }
    // As on the web: three columns, each a small label over its value.
    listOf(
            {{facts.0.term}} to {{facts.0.value}},
            {{facts.1.term}} to {{facts.1.value}},
            {{facts.2.term}} to {{facts.2.value}},
            {{facts.3.term}} to {{facts.3.value}},
    ).chunked(3).forEach { row ->
        Row(modifier = Modifier.fillMaxWidth()) {
            row.forEach { (label, value) ->
                Column(modifier = Modifier.weight(1f).padding(end = MonarchTheme.spacing.space2)) {
                    MonarchText(text = label, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        MonarchText(text = value ?: "—")
                        // As on the web: an icon-only copy button after the Contact ID.
                        if (label == "Contact ID" && value != null) {
                            MonarchCopyButton(
                                value = value,
                                icon = { MonarchIcon(SampleIcons.Copy, contentDescription = null, size = MonarchIconSize.Sm) },
                                label = "Copy " + label,
                            )
                        }
                    }
                }
            }
            repeat(3 - row.size) { Spacer(Modifier.weight(1f)) }
        }
    }
    MonarchTabs(selectedIndex = currentTab, onSelectedIndexChange = { currentTab = it }) {
        tab({{tabs.0}})
        tab({{tabs.1}})
        tab({{tabs.2}})
    }
}

